## Not run

- Nothing was checked for a **classic** (UI-created) App. Those live in another
  id space and are not in the beta list, so this says nothing about them.
- Only one App was renamed, once. Renaming twice, or renaming while a publish is
  in flight, was not tried.
MD
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$FINDINGS"
printf '\n'

if [[ "$NAME_AFTER" == "$NEW_NAME" ]]; then
  if confirm "Put the name back to \"$NAME_BEFORE\"?"; then
    api PATCH "/api/apps/beta/apps/$APP_ID" \
      "$(python3 -c 'import json,sys; print(json.dumps({"name": sys.argv[1]}))' "$NAME_BEFORE")" >/dev/null
    note "restore -> $API_STATUS"
  fi
fi
if grep -q "^LOST:" "$STATE_DIR/diff.txt" 2>/dev/null; then
  printf '\n'
  warn "the PATCH lost fields. $BEFORE holds what they were."
fi

printf '\n'
say "Next: read $FINDINGS, then take it back to #219."
note "rename works  -> ADR + both writers carry the name to the deployment"
note "rename cannot -> ADR, and Sage stops implying it does"
finish
